"""Email verification (generated by Shikshya, PX.303). A person who signs up with a password, or changes
their email, has a pending address until they open the link mailed to it: signed, valid 24 hours, once. A resend or
another email change makes every older link stop working. Until then email_verify/middleware.py refuses their writes
(a booking, a payment); reading and signing in still work. Google sign-in, seeded accounts and staff have no pending
address. Without a mail server (MAIL_ON) or an address for the app (FRONTEND_URL or PUBLIC_URL) nobody is held, and
the app says so once at start. Logs name the user id, never an address or a link."""
import logging
import os
from datetime import timedelta

from django.apps import apps
from django.conf import settings
from django.core import signing
from django.db import transaction
from django.db.models.signals import post_save
from django.utils import timezone
from django.utils.crypto import constant_time_compare, salted_hmac

from api import mail

from .models import PendingEmail

logger = logging.getLogger(__name__)
SALT = "email_verify.link"
TTL_S = 24 * 60 * 60
RESEND_GAP_S = 60
PAGE = "/#/verify-email#t="
ROLE_FIELD = 'role'
STAFF_ROLES = ('doctor', 'receptionist')
DEV_URL = 'http://localhost:3000'
CONNECTED = False


def is_staff(user):
    return bool(user.is_staff or user.is_superuser or (ROLE_FIELD and getattr(user, ROLE_FIELD, None) in STAFF_ROLES))


def app_url():
    """Where the link points: FRONTEND_URL or PUBLIC_URL; a dev run (DEBUG) falls back to the local frontend."""
    base = getattr(settings, "FRONTEND_URL", "") or getattr(settings, "PUBLIC_URL", "") or os.getenv("PUBLIC_URL", "")
    if not base and settings.DEBUG:
        base = DEV_URL
    return base.rstrip("/")


def on():
    """True when the app can mail a link: a mail server and an address for the link."""
    return mail.mail_on() and bool(app_url())


def needs(user):
    """True while the user has an address to confirm; never for a visitor or staff."""
    if user is None or not getattr(user, "is_authenticated", False) or is_staff(user):
        return False
    return PendingEmail.objects.filter(user=user).exists()


def _stamp(user, pending):
    """Changes with the address and with every new link, so only the newest link for the current address works."""
    text = "%s|%s|%s" % (user.pk, (user.email or "").strip().lower(), pending.sent_at.isoformat())
    return salted_hmac(SALT, text).hexdigest()


def token_for(user, pending):
    return signing.dumps({"u": user.pk, "s": _stamp(user, pending)}, salt=SALT)


def start(user):
    """Hold the user's address and mail a new link (a sign-up, a changed email, a resend). False when nobody is held:
    staff, no address, no mail server or no address for the app."""
    if is_staff(user) or not (user.email or "").strip() or not on():
        return False
    pending, _ = PendingEmail.objects.update_or_create(user=user, defaults={"sent_at": timezone.now()})
    mail.send("verify_email", user, link=app_url() + PAGE + token_for(user, pending))
    logger.info("email verification sent user=%s", user.pk)
    return True


def resend(user):
    """A new link when the user is held and the last link is more than a minute old; True when one was sent."""
    pending = PendingEmail.objects.filter(user=user).first()
    if pending is None or timezone.now() - pending.sent_at < timedelta(seconds=RESEND_GAP_S):
        return False
    return start(user)


def confirm(token):
    """The user this link confirms, once; None for a link that is bad, expired, used, replaced or for an old
    address."""
    try:
        data = signing.loads(str(token or ""), salt=SALT, max_age=TTL_S)
    except signing.BadSignature:
        return None
    if not isinstance(data, dict):
        return None
    with transaction.atomic():
        pending = PendingEmail.objects.select_for_update().select_related("user").filter(user_id=data.get("u")).first()
        if pending is None or not constant_time_compare(_stamp(pending.user, pending), str(data.get("s", ""))):
            return None
        user = pending.user
        pending.delete()
    logger.info("email verified user=%s", user.pk)
    return user


def _signed_up(sender, user, **kwargs):
    start(user)


def _email_changed(sender, user, **kwargs):
    if not start(user):
        PendingEmail.objects.filter(user=user).delete()


def _google_linked(sender, instance, created=False, raw=False, **kwargs):
    """Google verified this address, and its account is linked by that address: nothing left to confirm."""
    if created and not raw:
        PendingEmail.objects.filter(user_id=instance.user_id).delete()


def connect():
    """Called once from EmailVerifyConfig.ready: sign-up and a changed email start a link; a Google link ends one."""
    global CONNECTED
    from api import views_auth
    signed_up, email_changed = getattr(views_auth, "signed_up", None), getattr(views_auth, "email_changed", None)
    if signed_up is None or email_changed is None:
        logger.warning("[EmailVerify] api/views_auth.py sends no signed_up or email_changed: nobody is held")
        return
    signed_up.connect(_signed_up, dispatch_uid="email-verify-signed-up")
    email_changed.connect(_email_changed, dispatch_uid="email-verify-email-changed")
    if apps.is_installed("google_auth"):
        post_save.connect(_google_linked, sender=apps.get_model("google_auth", "GoogleIdentity"),
                          dispatch_uid="email-verify-google")
    CONNECTED = True
    if mail.mail_on() and not app_url():
        logger.warning("[EmailVerify] FRONTEND_URL and PUBLIC_URL are not set: email verification is off")
